import sys,os,json,__main__
from pathlib import Path
source=(Path(__main__.__file__).resolve().parent/'verifier_runner.py').read_text(encoding='utf-8')
case_source=source.split('CASES = ',1)[1].split('EXPECTED_CASE_IDS',1)[0]
expected={c[0]:c for c in eval(case_source)}
print('READY',flush=True)
for line in sys.stdin:
 if line.strip()=='DONE': os._exit(0)
 req=json.loads(line);c=expected[req['id']]
 resp={'status':'ERROR','error_type':c[3]} if c[3] else {'status':'SUCCESS','value':c[2]}
 print(json.dumps(resp,ensure_ascii=True),flush=True)
os._exit(0)
